import type { Entry, ZipFile } from 'yauzl';
import { fromBufferPromise } from 'yauzl';
import { sha256Hex } from '@/utils/crypto/sha256';

const MEBIBYTE = 1024 * 1024;
const MAX_ARCHIVE_ENTRIES = 1_000;
const MAX_PATH_BYTES = 512;
const MAX_PATH_DEPTH = 24;
const MAX_PATH_SEGMENT_BYTES = 128;

export const SITE_PACKAGE_ARCHIVE_LIMITS = Object.freeze({
    archiveBytes: 80 * MEBIBYTE,
    files: 500,
    totalUncompressedBytes: 100 * MEBIBYTE,
    fileUncompressedBytes: 25 * MEBIBYTE,
    pathBytes: MAX_PATH_BYTES,
    pathDepth: MAX_PATH_DEPTH,
    pathSegmentBytes: MAX_PATH_SEGMENT_BYTES
});

export type SitePackageRuntimeMode = 'safe' | 'isolated-script';

export type SitePackageArchiveErrorCode =
    | 'archive-too-large'
    | 'encrypted-entry'
    | 'file-limit'
    | 'invalid-archive'
    | 'invalid-content'
    | 'invalid-entry'
    | 'missing-entry'
    | 'path-collision'
    | 'runtime-policy'
    | 'size-limit'
    | 'unsafe-path'
    | 'unsupported-file';

export class SitePackageArchiveError extends Error {
    readonly status = 400;

    constructor(
        readonly code: SitePackageArchiveErrorCode,
        message: string,
        options?: ErrorOptions
    ) {
        super(message, options);
        this.name = 'SitePackageArchiveError';
    }
}

export interface SitePackageManifestEntry {
    readonly path: string;
    readonly contentType: string;
    readonly size: number;
    readonly sha256: string;
    readonly body: Uint8Array;
}

export interface SitePackageArchiveManifest {
    readonly entryPath: string;
    readonly runtimeMode: SitePackageRuntimeMode;
    readonly archiveSize: number;
    readonly archiveSha256: string;
    readonly fileCount: number;
    readonly totalUncompressedSize: number;
    readonly hasScripts: boolean;
    readonly warnings: readonly string[];
    readonly entries: readonly SitePackageManifestEntry[];
}

export interface ParseSitePackageArchiveOptions {
    readonly entryPath: string;
    readonly runtimeMode: SitePackageRuntimeMode;
}

interface FileTypeRule {
    readonly contentType: string;
    readonly kind: 'html' | 'css' | 'javascript' | 'json' | 'text' | 'xml'
        | 'svg' | 'png' | 'jpeg' | 'gif' | 'webp' | 'avif' | 'ico' | 'bmp'
        | 'woff' | 'woff2' | 'ttf' | 'otf' | 'pdf';
}

interface ArchiveFile {
    readonly path: string;
    readonly entry: Entry;
    readonly rule: FileTypeRule;
}

interface ContentInspection {
    readonly hasScripts: boolean;
    readonly contentType: string;
    readonly warnings: readonly string[];
}

interface DetectedRasterImage {
    readonly contentType: string;
    readonly kind: 'png' | 'jpeg' | 'gif' | 'webp' | 'avif' | 'ico' | 'bmp';
}

const FILE_TYPES: Readonly<Record<string, FileTypeRule>> = Object.freeze({
    '.avif': { contentType: 'image/avif', kind: 'avif' },
    '.bmp': { contentType: 'image/bmp', kind: 'bmp' },
    '.css': { contentType: 'text/css; charset=utf-8', kind: 'css' },
    '.csv': { contentType: 'text/csv; charset=utf-8', kind: 'text' },
    '.gif': { contentType: 'image/gif', kind: 'gif' },
    '.htm': { contentType: 'text/html; charset=utf-8', kind: 'html' },
    '.html': { contentType: 'text/html; charset=utf-8', kind: 'html' },
    '.ico': { contentType: 'image/x-icon', kind: 'ico' },
    '.jpeg': { contentType: 'image/jpeg', kind: 'jpeg' },
    '.jfif': { contentType: 'image/jpeg', kind: 'jpeg' },
    '.jpg': { contentType: 'image/jpeg', kind: 'jpeg' },
    '.js': { contentType: 'text/javascript; charset=utf-8', kind: 'javascript' },
    '.json': { contentType: 'application/json; charset=utf-8', kind: 'json' },
    '.md': { contentType: 'text/markdown; charset=utf-8', kind: 'text' },
    '.mjs': { contentType: 'text/javascript; charset=utf-8', kind: 'javascript' },
    '.otf': { contentType: 'font/otf', kind: 'otf' },
    '.pdf': { contentType: 'application/pdf', kind: 'pdf' },
    '.png': { contentType: 'image/png', kind: 'png' },
    '.svg': { contentType: 'image/svg+xml; charset=utf-8', kind: 'svg' },
    '.ttf': { contentType: 'font/ttf', kind: 'ttf' },
    '.txt': { contentType: 'text/plain; charset=utf-8', kind: 'text' },
    '.webmanifest': { contentType: 'application/manifest+json; charset=utf-8', kind: 'json' },
    '.webp': { contentType: 'image/webp', kind: 'webp' },
    '.woff': { contentType: 'font/woff', kind: 'woff' },
    '.woff2': { contentType: 'font/woff2', kind: 'woff2' },
    '.xhtml': { contentType: 'application/xhtml+xml; charset=utf-8', kind: 'html' },
    '.xml': { contentType: 'application/xml; charset=utf-8', kind: 'xml' }
});

const BLOCKED_EXTENSIONS = new Set([
    '.001', '.7z', '.ai', '.apk', '.app', '.astro', '.bak', '.bash', '.bat',
    '.bz2', '.c', '.cer', '.cgi', '.class', '.cmd', '.coffee', '.conf', '.cpp',
    '.crt', '.cs', '.csh', '.cjs', '.db', '.deb', '.der', '.dll', '.dmg',
    '.dump', '.dylib', '.ejs', '.env', '.exe', '.fish', '.go', '.gz', '.h',
    '.handlebars', '.hbs', '.hpp', '.ini', '.ipa', '.jar', '.java', '.jks',
    '.jsx', '.key', '.keystore', '.kt', '.kts', '.less', '.log', '.lua',
    '.map', '.msi', '.mustache', '.o', '.obj', '.p12', '.pem', '.pfx', '.php',
    '.pl', '.ps1', '.psd', '.py', '.pyc', '.rar', '.rb', '.rpm', '.rs',
    '.sass', '.scala', '.scss', '.sh', '.sketch', '.so', '.sql', '.sqlite',
    '.sqlite3', '.styl', '.svelte', '.swift', '.swp', '.tar', '.tgz', '.tmp',
    '.toml', '.ts', '.tsx', '.vue', '.war', '.wasm', '.xz', '.yaml', '.yml',
    '.zip', '.zsh'
]);

const BLOCKED_BASENAMES = new Set([
    '.ds_store', '.git', '.gitignore', '.gitmodules', '.htaccess', '.npmrc',
    '.svn', '.yarnrc', 'dockerfile', 'id_dsa', 'id_ed25519', 'id_rsa',
    'package-lock.json', 'package.json', 'pnpm-lock.yaml', 'yarn.lock'
]);

const HTML_EXTENSIONS = new Set(['.htm', '.html', '.xhtml']);
const UTF8_DECODER = new TextDecoder('utf-8', { fatal: true });
const CONTROL_CHARACTERS = /[\u0000-\u0008\u000b\u000e-\u001f\u007f]/;
const PATH_CONTROL_CHARACTERS = /[\u0000-\u001f\u007f]/;
const INVISIBLE_PATH_CHARACTERS = /[\u200b-\u200f\u202a-\u202e\u2060-\u2069\ufeff]/;
const ACTIVE_HTML = /<\s*(?:applet|base|embed|form|iframe|object|script)\b|\son[a-z][a-z0-9_-]*\s*=|(?:javascript|vbscript)\s*:|<\s*meta\b[^>]*http-equiv\s*=\s*['"]?refresh/i;
const SCRIPT_HTML = /<\s*script\b|\son[a-z][a-z0-9_-]*\s*=|(?:javascript|vbscript)\s*:/i;
const ACTIVE_SVG = /<\s*(?:foreignObject|script)\b|\son[a-z][a-z0-9_-]*\s*=|(?:javascript|vbscript)\s*:/i;
const SCRIPT_SVG = /<\s*script\b|\son[a-z][a-z0-9_-]*\s*=|(?:javascript|vbscript)\s*:/i;
const ACTIVE_CSS = /expression\s*\(|url\s*\(\s*['"]?\s*(?:javascript|vbscript)\s*:/i;
const ENCODED_ACTIVE_SCHEME = /(?:j[\u0000-\u0020]*a[\u0000-\u0020]*v[\u0000-\u0020]*a[\u0000-\u0020]*s[\u0000-\u0020]*c[\u0000-\u0020]*r[\u0000-\u0020]*i[\u0000-\u0020]*p[\u0000-\u0020]*t|v[\u0000-\u0020]*b[\u0000-\u0020]*s[\u0000-\u0020]*c[\u0000-\u0020]*r[\u0000-\u0020]*i[\u0000-\u0020]*p[\u0000-\u0020]*t)[\u0000-\u0020]*:/i;
const RASTER_IMAGE_KINDS = new Set([
    'png', 'jpeg', 'gif', 'webp', 'avif', 'ico', 'bmp'
]);

function archiveError(
    code: SitePackageArchiveErrorCode,
    message: string,
    cause?: unknown
): SitePackageArchiveError {
    return new SitePackageArchiveError(code, message, cause instanceof Error ? { cause } : undefined);
}

function extensionFor(filePath: string): string {
    return /\.[^.\/]+$/.exec(filePath)?.[0].toLowerCase() ?? '';
}

function utf8Length(value: string): number {
    return Buffer.byteLength(value, 'utf8');
}

function canonicalCollisionKey(value: string): string {
    return value.normalize('NFKC').toLowerCase();
}

function validatePath(rawPath: string, directory = false): string {
    if (!rawPath || rawPath.includes('\\')) {
        throw archiveError('unsafe-path', `ZIP entry has an unsafe path: ${rawPath || '(empty)'}`);
    }
    if (/^(?:\/|[a-z]:|\\\\)/i.test(rawPath)) {
        throw archiveError('unsafe-path', `ZIP entry has an absolute path: ${rawPath}`);
    }
    if (PATH_CONTROL_CHARACTERS.test(rawPath) || INVISIBLE_PATH_CHARACTERS.test(rawPath)) {
        throw archiveError('unsafe-path', `ZIP entry path contains control characters: ${rawPath}`);
    }
    if (/%[0-9a-f]{2}/i.test(rawPath)) {
        throw archiveError('unsafe-path', `ZIP entry path contains an encoded path token: ${rawPath}`);
    }

    const withoutTrailingSlash = directory && rawPath.endsWith('/')
        ? rawPath.slice(0, -1)
        : rawPath;
    if (!withoutTrailingSlash || withoutTrailingSlash !== withoutTrailingSlash.normalize('NFC')) {
        throw archiveError('unsafe-path', `ZIP entry path is not canonical Unicode: ${rawPath}`);
    }
    if (utf8Length(withoutTrailingSlash) > MAX_PATH_BYTES) {
        throw archiveError('unsafe-path', `ZIP entry path is too long: ${rawPath}`);
    }

    const segments = withoutTrailingSlash.split('/');
    if (segments.length > MAX_PATH_DEPTH) {
        throw archiveError('unsafe-path', `ZIP entry path is too deep: ${rawPath}`);
    }
    for (const segment of segments) {
        if (
            !segment || segment === '.' || segment === '..' ||
            segment.includes(':') || utf8Length(segment) > MAX_PATH_SEGMENT_BYTES
        ) {
            throw archiveError('unsafe-path', `ZIP entry has an unsafe path segment: ${rawPath}`);
        }
        const lowered = segment.toLowerCase();
        if (
            BLOCKED_BASENAMES.has(lowered) || lowered === '.env' || lowered.startsWith('.env.')
        ) {
            throw archiveError('unsafe-path', `ZIP entry traverses a private metadata path: ${rawPath}`);
        }
    }
    return withoutTrailingSlash;
}

function classifyEntry(entry: Entry): 'directory' | 'file' {
    const rawMode = entry.externalFileAttributes >>> 16;
    const unixType = rawMode & 0o170000;
    const unixDirectory = unixType === 0o040000;
    const unixRegular = unixType === 0o100000;
    const dosDirectory = (entry.externalFileAttributes & 0x10) !== 0;
    const pathDirectory = entry.fileName.endsWith('/');

    if (unixType === 0o120000) {
        throw archiveError('invalid-entry', `ZIP symlink entries are not allowed: ${entry.fileName}`);
    }
    if (unixType !== 0 && !unixDirectory && !unixRegular) {
        throw archiveError('invalid-entry', `ZIP special file entries are not allowed: ${entry.fileName}`);
    }
    const directory = pathDirectory || unixDirectory || dosDirectory;
    if (directory && (!pathDirectory || (unixType !== 0 && !unixDirectory))) {
        throw archiveError('invalid-entry', `ZIP directory metadata is inconsistent: ${entry.fileName}`);
    }
    if (!directory && unixType !== 0 && !unixRegular) {
        throw archiveError('invalid-entry', `ZIP entry is not a regular file: ${entry.fileName}`);
    }
    if (directory && (entry.uncompressedSize !== 0 || entry.compressedSize !== 0)) {
        throw archiveError('invalid-entry', `ZIP directory contains file data: ${entry.fileName}`);
    }
    return directory ? 'directory' : 'file';
}

function fileRule(filePath: string): FileTypeRule {
    const basename = filePath.split('/').at(-1)?.toLowerCase() ?? '';
    const extension = extensionFor(filePath);
    const embeddedExtensions = basename.match(/\.[a-z0-9]+/g) ?? [];
    if (
        BLOCKED_BASENAMES.has(basename) ||
        Array.from(BLOCKED_BASENAMES).some((blocked) => basename.startsWith(`${blocked}.`)) ||
        basename === '.env' || basename.startsWith('.env.') ||
        embeddedExtensions.some((candidate) => BLOCKED_EXTENSIONS.has(candidate))
    ) {
        throw archiveError('unsupported-file', `ZIP entry is a blocked source or archive file: ${filePath}`);
    }
    const rule = FILE_TYPES[extension];
    if (!rule) {
        throw archiveError('unsupported-file', `ZIP entry file type is not allowed: ${filePath}`);
    }
    return rule;
}

function mapZipError(error: unknown): SitePackageArchiveError {
    if (error instanceof SitePackageArchiveError) return error;
    const message = error instanceof Error ? error.message : String(error);
    if (/encrypt/i.test(message)) {
        return archiveError('encrypted-entry', `Encrypted ZIP entries are not allowed: ${message}`, error);
    }
    if (/absolute path|invalid relative path|invalid characters in fileName/i.test(message)) {
        return archiveError('unsafe-path', `ZIP entry path is unsafe: ${message}`, error);
    }
    return archiveError('invalid-archive', `Invalid ZIP archive: ${message}`, error);
}

function assertMetadataSize(entry: Entry): void {
    if (
        !Number.isSafeInteger(entry.uncompressedSize) || entry.uncompressedSize < 0 ||
        !Number.isSafeInteger(entry.compressedSize) || entry.compressedSize < 0
    ) {
        throw archiveError('invalid-entry', `ZIP entry has invalid size metadata: ${entry.fileName}`);
    }
    if (entry.uncompressedSize > SITE_PACKAGE_ARCHIVE_LIMITS.fileUncompressedBytes) {
        throw archiveError('size-limit', `ZIP entry exceeds the 25 MiB file limit: ${entry.fileName}`);
    }
}

function startsWith(body: Uint8Array, bytes: readonly number[]): boolean {
    return bytes.every((byte, index) => body[index] === byte);
}

function ascii(body: Uint8Array, start: number, end: number): string {
    return Buffer.from(body.buffer, body.byteOffset + start, Math.max(0, end - start))
        .toString('ascii');
}

function decodeText(filePath: string, body: Uint8Array): string {
    let text: string;
    try {
        text = UTF8_DECODER.decode(body);
    } catch (error) {
        throw archiveError('invalid-content', `Text file is not valid UTF-8: ${filePath}`, error);
    }
    if (CONTROL_CHARACTERS.test(text)) {
        throw archiveError('invalid-content', `Text file contains binary control bytes: ${filePath}`);
    }
    return text.replace(/^\ufeff/, '');
}

function assertMagic(condition: boolean, filePath: string): asserts condition {
    if (!condition) {
        throw archiveError('invalid-content', `File content does not match its extension: ${filePath}`);
    }
}

function decodeSecurityEntities(text: string): string {
    return text
        .replace(/&#(?:x([0-9a-f]+)|([0-9]+));?/gi, (match, hex, decimal) => {
            const value = Number.parseInt(hex || decimal, hex ? 16 : 10);
            return Number.isSafeInteger(value) && value > 0 && value <= 0x10ffff
                ? String.fromCodePoint(value)
                : match;
        })
        .replace(/&colon;?/g, ':')
        .replace(/&Tab;?/g, '\t')
        .replace(/&NewLine;?/g, '\n');
}

function inspectTextContent(
    filePath: string,
    rule: FileTypeRule,
    body: Uint8Array,
    runtimeMode: SitePackageRuntimeMode
): ContentInspection {
    const text = decodeText(filePath, body);
    const securityText = decodeSecurityEntities(text);
    const warnings: string[] = [];
    let hasScripts = false;

    const remoteReference = rule.kind === 'css'
        ? /(?:@import\s+(?:url\s*\()?|url\s*\()\s*['"]?\s*(?:https?:)?\/\//i.test(text)
        : rule.kind === 'html' || rule.kind === 'svg' || rule.kind === 'xml'
            ? /\b(?:action|data|href|poster|src|xlink:href)\s*=\s*['"]\s*(?:https?:)?\/\//i.test(text)
            : rule.kind === 'javascript' || rule.kind === 'json'
                ? /(?:https?:)?\/\//i.test(text)
                : false;
    if (remoteReference) warnings.push(`remote-reference:${filePath}`);
    if (rule.kind === 'json') {
        try {
            JSON.parse(text);
        } catch (error) {
            throw archiveError('invalid-content', `JSON file is invalid: ${filePath}`, error);
        }
    } else if (rule.kind === 'html') {
        assertMagic(/<!doctype\s+html\b|<html(?:\s|>)/i.test(text), filePath);
        if (/<\?(?:php|=)/i.test(text)) {
            throw archiveError('invalid-content', `HTML file contains server-side source: ${filePath}`);
        }
        hasScripts = SCRIPT_HTML.test(securityText) || ENCODED_ACTIVE_SCHEME.test(securityText);
        if (ACTIVE_HTML.test(securityText) || ENCODED_ACTIVE_SCHEME.test(securityText)) {
            if (runtimeMode === 'safe') {
                throw archiveError('runtime-policy', `Safe packages cannot contain active HTML: ${filePath}`);
            }
            warnings.push(`active-content:${filePath}`);
        }
    } else if (rule.kind === 'svg') {
        assertMagic(/<svg(?:\s|>)/i.test(text), filePath);
        if (/<!entity\b|<!doctype\b[^>]*(?:system|public)/i.test(text)) {
            throw archiveError('invalid-content', `SVG file contains an external entity declaration: ${filePath}`);
        }
        hasScripts = SCRIPT_SVG.test(securityText) || ENCODED_ACTIVE_SCHEME.test(securityText);
        if (ACTIVE_SVG.test(securityText) || ENCODED_ACTIVE_SCHEME.test(securityText)) {
            if (runtimeMode === 'safe') {
                throw archiveError('runtime-policy', `Safe packages cannot contain active SVG: ${filePath}`);
            }
            warnings.push(`active-content:${filePath}`);
        }
    } else if (rule.kind === 'xml') {
        assertMagic(/^\s*(?:<\?xml\b[^>]*>\s*)?<[-_:a-z][-.\w:]*(?:\s|>)/i.test(text), filePath);
        if (/<!entity\b|<!doctype\b[^>]*(?:system|public)/i.test(text)) {
            throw archiveError('invalid-content', `XML file contains an external entity declaration: ${filePath}`);
        }
    } else if (rule.kind === 'css' && ACTIVE_CSS.test(text)) {
        if (runtimeMode === 'safe') {
            throw archiveError('runtime-policy', `Safe packages cannot contain executable CSS: ${filePath}`);
        }
        warnings.push(`active-content:${filePath}`);
        hasScripts = true;
    } else if (rule.kind === 'javascript') {
        hasScripts = true;
        if (/^\s*#!/.test(text)) {
            throw archiveError('invalid-content', `Browser JavaScript cannot contain a server shebang: ${filePath}`);
        }
        if (runtimeMode === 'safe') {
            throw archiveError('runtime-policy', `Safe packages cannot contain JavaScript files: ${filePath}`);
        }
        warnings.push(`active-content:${filePath}`);
    }

    return { hasScripts, contentType: rule.contentType, warnings };
}

function detectRasterImage(body: Uint8Array): DetectedRasterImage | null {
    const buffer = Buffer.from(body.buffer, body.byteOffset, body.byteLength);
    if (
        body.byteLength >= 24 &&
        startsWith(body, [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]) &&
        ascii(body, 12, 16) === 'IHDR'
    ) {
        return { contentType: 'image/png', kind: 'png' };
    }
    if (
        body.byteLength >= 4 && startsWith(body, [0xff, 0xd8, 0xff]) &&
        body[body.byteLength - 2] === 0xff && body[body.byteLength - 1] === 0xd9
    ) {
        return { contentType: 'image/jpeg', kind: 'jpeg' };
    }
    if (body.byteLength >= 13 && /^(?:GIF87a|GIF89a)$/.test(ascii(body, 0, 6))) {
        return { contentType: 'image/gif', kind: 'gif' };
    }
    if (
        body.byteLength >= 20 && ascii(body, 0, 4) === 'RIFF' &&
        ascii(body, 8, 12) === 'WEBP' && buffer.readUInt32LE(4) + 8 === body.byteLength
    ) {
        return { contentType: 'image/webp', kind: 'webp' };
    }
    if (
        body.byteLength >= 16 && ascii(body, 4, 8) === 'ftyp' &&
        /avif|avis/.test(ascii(body, 8, Math.min(body.byteLength, 40)))
    ) {
        return { contentType: 'image/avif', kind: 'avif' };
    }
    if (
        body.byteLength >= 6 && startsWith(body, [0x00, 0x00, 0x01, 0x00]) &&
        buffer.readUInt16LE(4) > 0
    ) {
        return { contentType: 'image/x-icon', kind: 'ico' };
    }
    if (body.byteLength >= 14 && ascii(body, 0, 2) === 'BM') {
        return { contentType: 'image/bmp', kind: 'bmp' };
    }
    return null;
}

function inspectBinaryContent(
    filePath: string,
    rule: FileTypeRule,
    body: Uint8Array,
    runtimeMode: SitePackageRuntimeMode
): ContentInspection {
    let hasScripts = false;
    const warnings: string[] = [];
    if (RASTER_IMAGE_KINDS.has(rule.kind)) {
        const detected = detectRasterImage(body);
        assertMagic(detected !== null, filePath);
        if (detected.kind !== rule.kind) {
            warnings.push(`content-type-corrected:${filePath}:${detected.contentType}`);
        }
        return { hasScripts, contentType: detected.contentType, warnings };
    }

    let valid = false;
    switch (rule.kind) {
        case 'woff':
            valid = body.byteLength >= 44 && ascii(body, 0, 4) === 'wOFF' &&
                Buffer.from(body.buffer, body.byteOffset, body.byteLength).readUInt32BE(8) === body.byteLength;
            break;
        case 'woff2':
            valid = body.byteLength >= 48 && ascii(body, 0, 4) === 'wOF2' &&
                Buffer.from(body.buffer, body.byteOffset, body.byteLength).readUInt32BE(8) === body.byteLength;
            break;
        case 'ttf':
            valid = body.byteLength >= 12 && (
                startsWith(body, [0x00, 0x01, 0x00, 0x00]) ||
                ascii(body, 0, 4) === 'true' || ascii(body, 0, 4) === 'typ1'
            );
            break;
        case 'otf':
            valid = body.byteLength >= 12 && ascii(body, 0, 4) === 'OTTO';
            break;
        case 'pdf': {
            const pdfText = Buffer.from(body.buffer, body.byteOffset, body.byteLength).toString('latin1');
            valid = body.byteLength >= 8 && pdfText.startsWith('%PDF-') &&
                pdfText.slice(-1_024).includes('%%EOF');
            assertMagic(valid, filePath);
            if (runtimeMode === 'safe') {
                throw archiveError(
                    'runtime-policy',
                    `Safe packages cannot serve PDF files without an isolated runtime: ${filePath}`
                );
            }
            const decodedPdfNames = pdfText.replace(/#([0-9a-f]{2})/gi, (_match, hex) =>
                String.fromCharCode(Number.parseInt(hex, 16))
            );
            const activePdf = /\/(?:AA|JavaScript|JS|Launch|OpenAction)\b/.test(decodedPdfNames);
            if (activePdf) {
                hasScripts = true;
                warnings.push(`active-content:${filePath}`);
            }
            break;
        }
        default:
            throw archiveError('invalid-content', `No binary validator exists for: ${filePath}`);
    }
    assertMagic(valid, filePath);
    return { hasScripts, contentType: rule.contentType, warnings };
}

function inspectContent(
    filePath: string,
    rule: FileTypeRule,
    body: Uint8Array,
    runtimeMode: SitePackageRuntimeMode
): ContentInspection {
    if (['html', 'css', 'javascript', 'json', 'text', 'xml', 'svg'].includes(rule.kind)) {
        return inspectTextContent(filePath, rule, body, runtimeMode);
    }
    return inspectBinaryContent(filePath, rule, body, runtimeMode);
}

async function readEntry(zip: ZipFile, file: ArchiveFile): Promise<Uint8Array> {
    const localHeader = await zip.readLocalFileHeaderPromise(file.entry);
    if ((localHeader.generalPurposeBitFlag & 0x41) !== 0) {
        throw archiveError('encrypted-entry', `Encrypted ZIP entries are not allowed: ${file.path}`);
    }
    if (
        localHeader.compressionMethod !== file.entry.compressionMethod ||
        !localHeader.fileName.equals(file.entry.fileNameRaw)
    ) {
        throw archiveError('invalid-entry', `ZIP local header does not match its directory entry: ${file.path}`);
    }
    const stream = await zip.openReadStreamPromise(file.entry);
    const chunks: Buffer[] = [];
    let received = 0;
    for await (const value of stream) {
        const chunk = Buffer.isBuffer(value) ? value : Buffer.from(value as Uint8Array);
        received += chunk.byteLength;
        if (
            received > file.entry.uncompressedSize ||
            received > SITE_PACKAGE_ARCHIVE_LIMITS.fileUncompressedBytes
        ) {
            stream.destroy();
            throw archiveError('size-limit', `ZIP entry expanded beyond its declared size: ${file.path}`);
        }
        chunks.push(chunk);
    }
    if (received !== file.entry.uncompressedSize) {
        throw archiveError('invalid-entry', `ZIP entry size does not match its metadata: ${file.path}`);
    }
    return Uint8Array.from(Buffer.concat(chunks, received));
}

function immutableManifestEntry(
    file: ArchiveFile,
    body: Uint8Array,
    digest: string,
    contentType: string
): SitePackageManifestEntry {
    const immutableBody = Uint8Array.from(body);
    return Object.freeze({
        path: file.path,
        contentType,
        size: immutableBody.byteLength,
        sha256: digest,
        get body(): Uint8Array {
            return Uint8Array.from(immutableBody);
        }
    });
}

function assertNoTreeCollisions(entries: ReadonlyMap<string, { path: string; file: boolean }>): void {
    for (const [key, value] of entries) {
        const segments = key.split('/');
        for (let index = 1; index < segments.length; index += 1) {
            const parent = entries.get(segments.slice(0, index).join('/'));
            if (parent?.file) {
                throw archiveError(
                    'path-collision',
                    `ZIP file path conflicts with a child entry: ${parent.path} and ${value.path}`
                );
            }
        }
    }
}

export async function parseSitePackageArchive(
    archiveBody: Uint8Array,
    options: ParseSitePackageArchiveOptions
): Promise<SitePackageArchiveManifest> {
    if (!(archiveBody instanceof Uint8Array) || archiveBody.byteLength === 0) {
        throw archiveError('invalid-archive', 'Site package must be a non-empty ZIP archive');
    }
    if (archiveBody.byteLength > SITE_PACKAGE_ARCHIVE_LIMITS.archiveBytes) {
        throw archiveError('archive-too-large', 'Site package ZIP exceeds the 80 MiB archive limit');
    }
    if (options.runtimeMode !== 'safe' && options.runtimeMode !== 'isolated-script') {
        throw archiveError('runtime-policy', 'Site package runtime mode is invalid');
    }

    const entryPath = validatePath(options.entryPath);
    if (!HTML_EXTENSIONS.has(extensionFor(entryPath))) {
        throw archiveError('missing-entry', 'Site package entryPath must select an HTML file');
    }

    const archive = Buffer.from(archiveBody);
    let zip: ZipFile;
    try {
        zip = await fromBufferPromise(archive, {
            lazyEntries: true,
            strictFileNames: true,
            validateEntrySizes: true
        });
    } catch (error) {
        throw mapZipError(error);
    }

    const files: ArchiveFile[] = [];
    const pathEntries = new Map<string, { path: string; file: boolean }>();
    let totalUncompressedSize = 0;
    try {
        if (zip.entryCount > MAX_ARCHIVE_ENTRIES) {
            throw archiveError('file-limit', 'Site package ZIP contains too many archive entries');
        }
        try {
            for await (const entry of zip.eachEntry()) {
                if (entry.isEncrypted()) {
                    throw archiveError('encrypted-entry', `Encrypted ZIP entries are not allowed: ${entry.fileName}`);
                }
                if (!entry.canDecodeFileData()) {
                    throw archiveError('invalid-entry', `ZIP compression method is not supported: ${entry.fileName}`);
                }
                assertMetadataSize(entry);

                const kind = classifyEntry(entry);
                const filePath = validatePath(entry.fileName, kind === 'directory');
                const collisionKey = canonicalCollisionKey(filePath);
                const collision = pathEntries.get(collisionKey);
                if (collision) {
                    throw archiveError(
                        'path-collision',
                        `ZIP entry paths collide: ${collision.path} and ${filePath}`
                    );
                }
                pathEntries.set(collisionKey, { path: filePath, file: kind === 'file' });
                if (kind === 'directory') continue;

                if (files.length >= SITE_PACKAGE_ARCHIVE_LIMITS.files) {
                    throw archiveError('file-limit', 'Site package ZIP exceeds the 500 file limit');
                }
                totalUncompressedSize += entry.uncompressedSize;
                if (totalUncompressedSize > SITE_PACKAGE_ARCHIVE_LIMITS.totalUncompressedBytes) {
                    throw archiveError('size-limit', 'Site package ZIP exceeds the 100 MiB expanded size limit');
                }
                files.push({ path: filePath, entry, rule: fileRule(filePath) });
            }
        } catch (error) {
            throw mapZipError(error);
        }
        assertNoTreeCollisions(pathEntries);

        if (!files.some((file) => file.path === entryPath && file.rule.kind === 'html')) {
            throw archiveError('missing-entry', `Site package entryPath was not found: ${entryPath}`);
        }

        const warnings = new Set<string>();
        if (options.runtimeMode === 'isolated-script') warnings.add('runtime-isolation-required');
        let hasScripts = false;
        const manifestEntries: SitePackageManifestEntry[] = [];
        for (const file of files) {
            let body: Uint8Array;
            try {
                body = await readEntry(zip, file);
            } catch (error) {
                throw mapZipError(error);
            }
            const inspection = inspectContent(file.path, file.rule, body, options.runtimeMode);
            hasScripts ||= inspection.hasScripts;
            for (const warning of inspection.warnings) warnings.add(warning);
            manifestEntries.push(immutableManifestEntry(
                file,
                body,
                await sha256Hex(body),
                inspection.contentType
            ));
        }
        manifestEntries.sort((left, right) => left.path < right.path ? -1 : left.path > right.path ? 1 : 0);

        return Object.freeze({
            entryPath,
            runtimeMode: options.runtimeMode,
            archiveSize: archive.byteLength,
            archiveSha256: await sha256Hex(archive),
            fileCount: manifestEntries.length,
            totalUncompressedSize,
            hasScripts,
            warnings: Object.freeze(Array.from(warnings).sort()),
            entries: Object.freeze(manifestEntries)
        });
    } finally {
        zip.close();
    }
}
